//! The one FFI boundary of this crate.
//!
//! `bindings.rs` is generated by `build.rs` from `rust/wrapper.h`, which
//! includes ONLY our private shim (`src/core_shim.h`). The vendored box64
//! headers never reach the Rust compiler, so no box64 private type can leak into
//! the business code; everything vendor-specific goes through `box64dl_core_*`.

#![allow(non_upper_case_globals)]
#![allow(non_camel_case_types)]
#![allow(non_snake_case)]
#![allow(dead_code)]

include!(concat!(env!("OUT_DIR"), "/bindings.rs"));

/// Opaque box64 context. Rust holds it as an identity handle only; it never
/// dereferences it. The C shim owns all access to the real structure.
#[repr(C)]
pub struct c_box64_ctx {
    _opaque: [u8; 0],
}

/// Opaque per-thread x64emu_t. Same rule: identity only.
#[repr(C)]
pub struct c_x64emu_t {
    _opaque: [u8; 0],
}
